import{_ as l,a0 as d,w as r,s as o,I as n,x as a,a1 as i,A as t,ao as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"在 Linux 上使用 GNU Parted 對磁盤分區 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 上使用 GNU Parted 對磁盤分區 | LCTT (202204) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 上使用 GNU Parted 對磁盤分區 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 上使用 GNU Parted 對磁盤分區 | LCTT (202204) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202204/20210401 Partition a drive on Linux with GNU Parted","title":"在 Linux 上使用 GNU Parted 對磁盤分區","tag":"202204","desc":""},"relativePath":"202204/20210401 Partition a drive on Linux with GNU Parted.md","filePath":"[post].md"}'),h={name:"202204/20210401 Partition a drive on Linux with GNU Parted.md"};function u(g,s,k,b,c,m){const e=d("Link");return r(),o("div",null,[s[23]||(s[23]=n("h1",{id:"在-linux-上使用-gnu-parted-對磁盤分區",tabindex:"-1"},[a("在 Linux 上使用 GNU Parted 對磁盤分區 "),n("a",{class:"header-anchor",href:"#在-linux-上使用-gnu-parted-對磁盤分區","aria-label":"Permalink to “在 Linux 上使用 GNU Parted 對磁盤分區”"},"​")],-1)),s[24]||(s[24]=n("blockquote",null,[n("p",null,"瞭解對新的儲存設備分區的基礎知識，然後下載我們的速查表，讓信息近在咫尺。")],-1)),s[25]||(s[25]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202204/12/162040edndfpnkn8233ppd.jpg",alt:""})],-1)),s[26]||(s[26]=n("p",null,"在 21 世紀，我們往往認為數據存儲是理所當然的。我們有許多存儲介質，相對價格便宜，而且有許多不同的可用類型。然而，不論你獲得的免費雲存儲空間有多少，沒有比有一個物理硬盤空間來存儲重要的數據更好了（或容量真的很大的，而當你又在一個慢速網絡上時）。然而，沒有幾塊硬盤買回來就是現成的，至少在理想的狀況下可以直接使用的。無論你是買了一塊新硬盤，還用不同分區安裝一個系統，你需要知道怎麼在 Linux 上為磁盤分區。",-1)),n("p",null,[s[1]||(s[1]=a("這篇文章介紹了 GNU Parted ，它磁盤分區最好的工具之一。如果你偏向使用圖形化程序，而不算終端命令列，請閲讀我的《",-1)),i(e,{href:"https://opensource.com/article/18/11/partition-format-drive-linux#gui"},{default:t(()=>[...s[0]||(s[0]=[a("為 Linux 格式化驅動器",-1)])]),_:1}),s[2]||(s[2]=a("》這篇文章。",-1))]),s[27]||(s[27]=p('<h3 id="磁盤標籤、分區和文件系統" tabindex="-1">磁盤標籤、分區和文件系統 <a class="header-anchor" href="#磁盤標籤、分區和文件系統" aria-label="Permalink to “磁盤標籤、分區和文件系統”">​</a></h3><p>技術上來説，一個硬盤驅動器不需要很多軟件，就可用作存儲設備。然而，在沒有分區表和文件系統等現代慣例的情況下使用硬盤是困難的、不切實際的，而且對你的數據不安全。</p><p>關於硬盤驅動器，這裏有三個你需要知道的重要概念：</p><ul><li><ruby>磁盤標籤<rt>disk label</rt></ruby>（或者 <ruby>分區表<rt>partition table</rt></ruby>）是放置在磁盤驅動器起始位置的元數據，它告訴計算機可用的存儲是何種類型、以及它在磁盤驅動器的位置等信息。</li><li><ruby>分區<rt>partition</rt></ruby> 是一個識別文件系統位置的邊界。舉個例子，如果你有一個 512GB 的硬盤，你可以用佔用所有磁盤容量（512GB）分成一個分區，或者分成兩個分區，每個佔用 256GB ，或者分成三個分區，佔用各種不同大小的空間等等。</li><li><ruby>文件系統<rt>filesystem</rt></ruby> 是一個硬盤驅動器和計算機兩者約定俗成的存儲方案。計算機必須知道怎樣讀取文件系統來拼湊存儲在驅動器上的數據，並且必須知道怎樣寫入數據到文件系統並保持數據的完整性。</li></ul><p>GNU Parted 程序管理着前兩個概念：磁盤標籤和分區。Parted 對文件系統有所瞭解，但是它把文件系統的實現細節交給了其他類似 <code>mkfs</code> 這樣的工具。</p>',5)),n("blockquote",null,[n("p",null,[s[4]||(s[4]=a("下載 ",-1)),i(e,{href:"https://opensource.com/downloads/parted-cheat-sheet"},{default:t(()=>[...s[3]||(s[3]=[a("GNU Parted 速查表",-1)])]),_:1})])]),s[28]||(s[28]=p(`<h3 id="確定磁盤驅動器的位置" tabindex="-1">確定磁盤驅動器的位置 <a class="header-anchor" href="#確定磁盤驅動器的位置" aria-label="Permalink to “確定磁盤驅動器的位置”">​</a></h3><p>使用 GNU Parted 之前，你必須確定你的驅動器在你的系統上的位置。首先，將你要格式化的磁盤驅動器連接到你的系統，然後用 <code>parted</code> 命令查看連接到你的計算機的設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sda print devices</span></span>
<span class="line"><span>/dev/sda (2000GB)</span></span>
<span class="line"><span>/dev/sdb (1000GB)</span></span>
<span class="line"><span>/dev/sdc (1940MB)</span></span></code></pre></div><p>你最新連接設備的名稱在字母表上晚於連接時間更長的設備。舉個例子，<code>/dev/sdc</code> 最有可能是我剛剛連接的磁盤。我能通過它的容量大小來確認，相比於我的工作站上的主要驅動器的 TB 大小來説，因為我知道我插入的 U 盤只有 2GB（1940MB，足夠接近）大小。如果你不能確定，你可以得到的更多關於你想要分區的驅動器的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdc print</span></span>
<span class="line"><span>Model: Yoyodyne Tiny Drive 1.0 (scsi)    </span></span>
<span class="line"><span>Disk /dev/sdc: 1940MB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: msdos</span></span>
<span class="line"><span>Disk Flags:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End     Size    File system  Name  Flags</span></span>
<span class="line"><span> 1      1049kB  2048kB  1024kB  BS           Bloat  Hidden</span></span>
<span class="line"><span> 2      2049kB  1939MB  1937MB  FAT32        MyDrive</span></span></code></pre></div><p>有些驅動器比其他驅動器有更多的元數據。這個磁盤表明它的物理驅動器品牌是 Yoyodyne ，此外，在磁盤的起始處包含了一個小的隱藏分區，後面是一個兼容 Windows 的臃腫的 FAT32 分區。這確實是我要重新打算格式化的驅動器。</p><p>繼續之前，<em>確認</em> 你已經確定了要分區的正確驅動器。 <em>對錯誤的驅動器重新分區會導致數據丟失。</em> 為了安全起見，在本文中所有具有潛在破環性的命令都指向在你的系統中不太可能有的 <code>/dev/sdX</code> 設備。</p><h3 id="創建磁盤標籤-或者分區表" tabindex="-1">創建磁盤標籤（或者分區表） <a class="header-anchor" href="#創建磁盤標籤-或者分區表" aria-label="Permalink to “創建磁盤標籤（或者分區表）”">​</a></h3><p>要在磁盤上創建一個分區，驅動器必須要有一個<ruby>磁盤標籤<rt>disk label</rt></ruby>。磁盤標籤也被叫做 <ruby>分區表<rt>partition table</rt></ruby>，所以 Parted 對兩個術語都接受。</p><p>要創建一個磁盤卷標，使用 <code>mklabel</code> 或 <code>mktable</code> 子命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX mklabel gpt</span></span></code></pre></div><p>這個命令在 <code>/dev/sdX</code> 的驅動器前面創建了一個 <strong>gpt</strong> 標籤，刪除了任何可能存在的標籤。這是一個快速的過程，因為所有被替換的信息都是關於分區的元數據。</p><h3 id="創建分區" tabindex="-1">創建分區 <a class="header-anchor" href="#創建分區" aria-label="Permalink to “創建分區”">​</a></h3><p>要在磁盤創建分區，使用 <code>mkpart</code> 子命令，後跟可選的分區名稱，再跟分區的開始和結束位置。如果你在磁盤上只需要一個分區，那麼大小調整是容易的：開始位置輸入 1 ，結束位置輸入 100% 。使用 <code>--align opt</code> 參數允許 Parted 調整分區邊界位置便於磁盤獲得最佳性能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX --align opt \\</span></span>
<span class="line"><span>mkpart example 1 100%</span></span></code></pre></div><p>用 <code>print</code> 子命令查看你的新分區：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX print</span></span>
<span class="line"><span>Model: Yoyodyne Tiny Drive 1.0 (scsi)</span></span>
<span class="line"><span>Disk /dev/sdi: 1940MB</span></span>
<span class="line"><span>Sector size (logical/physical): 512B/512B</span></span>
<span class="line"><span>Partition Table: gpt</span></span>
<span class="line"><span>Disk Flags:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Number  Start   End     Size  </span></span>
<span class="line"><span> 1      1049kB  1939MB  1938MB</span></span></code></pre></div><p>你不必將整個磁盤用作一個分區。分區的優勢是在一個磁盤上可以存在多個文件系統，它們之間不會相互干擾。在確定分區大小的時候，你可以使用 <code>unit</code> 子命令來設置你想用的測量方法。Parted 可以理解<ruby>扇區<rt>sector</rt></ruby>、<ruby>柱面<rt>cylinder</rt></ruby>、<ruby>磁頭<rt>head</rt></ruby>、<ruby>字節<rt>byte</rt></ruby>、KB、MB、GB、TB 和百分比。（LCTT 譯註：具體使用方法請參閲手冊頁）</p><p>你也可以指定你打算使用的分區的文件系統。這並不會創建文件系統，但是它為你以後方便使用提供了元數據。</p><p>將磁盤對半分，一個是 XFS 文件系統，另一個是 EXT4 文件系統：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX --align opt \\</span></span>
<span class="line"><span>mkpart xfs 1 50%</span></span>
<span class="line"><span>$ parted /dev/sdX --align opt \\</span></span>
<span class="line"><span>mkpart ext4 51% 100%</span></span></code></pre></div><h3 id="命名分區" tabindex="-1">命名分區 <a class="header-anchor" href="#命名分區" aria-label="Permalink to “命名分區”">​</a></h3><p>除了標記分區用於什麼文件系統之外，你也可以為每個分區命名。一些文件管理器和工具可以讀取分區名稱，能夠幫助你區分驅動器。例如，我經常有幾個不同的驅動器連接到我的媒體工作站，每個屬於一個不同的項目。當創建這些驅動器的時候，我同時命名了分區和文件系統，這樣，無論我怎麼看我的系統，有重要數據的位置都會被清楚地標示出來。</p><p>要命名一個分區，你必須知道它的序號：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX print</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Number  Start   End     Size   File system  Name     Flags</span></span>
<span class="line"><span> 1      1049kB  990MB   989MB  xfs          example</span></span>
<span class="line"><span> 2      1009MB  1939MB  930MB  ext4         noname</span></span></code></pre></div><p>要命名分區 1：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX name 1 example</span></span>
<span class="line"><span>$ parted /dev/sdX print</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Number  Start   End     Size   File system  Name     Flags</span></span>
<span class="line"><span> 1      1049kB  990MB   989MB  xfs          example</span></span>
<span class="line"><span> 2      1009MB  1939MB  930MB  ext4         noname</span></span></code></pre></div><h3 id="創建文件系統" tabindex="-1">創建文件系統 <a class="header-anchor" href="#創建文件系統" aria-label="Permalink to “創建文件系統”">​</a></h3><p>要讓你的驅動器能夠正常使用，你必須在新分區上創建一個文件系統。GNU Parted 並不做這些，因為它只是一個分區管理器。在磁盤上創建文件系統的 Linux 命令是 <code>mkfs</code>，但也有一些有用的工具可以讓你用來創建特定類型的文件系統。例如，<code>mkfs.ext4</code> 創建 EXT4 文件系統，<code>mkfs.xfs</code> 創建 XFS 文件系統等等。</p><p>你的分區位於磁盤驅動器的“內部” ，所以你不是在 <code>/dev/sdX</code> 上創建文件系統，而是在 <code>/dev/sdX1</code> 上為第一個分區創建文件系統，在 <code>/dev/sdX2</code> 上為第二個分區創建，以此類推。</p><p>這裏是一個創建 XFS 文件系統的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo mkfs.xfs -L mydrive /dev/sdX1</span></span></code></pre></div><h3 id="下載我們的速查表" tabindex="-1">下載我們的速查表 <a class="header-anchor" href="#下載我們的速查表" aria-label="Permalink to “下載我們的速查表”">​</a></h3><p>Parted 是一個靈活而強大的工具。你可以發出命令，如本文所示的那樣，或者激活一個交互模式以不斷 “連接” 你指定的驅動器:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ parted /dev/sdX</span></span>
<span class="line"><span>(parted) print</span></span>
<span class="line"><span>[...]</span></span>
<span class="line"><span>Number  Start   End     Size   File system  Name     Flags</span></span>
<span class="line"><span> 1      1049kB  990MB   989MB  xfs          example</span></span>
<span class="line"><span> 2      1009MB  1939MB  930MB  ext4         noname</span></span>
<span class="line"><span></span></span>
<span class="line"><span>(parted) name 1 mydrive</span></span>
<span class="line"><span>(parted)</span></span></code></pre></div>`,35)),n("p",null,[s[6]||(s[6]=a("如果你打算經常使用 Parted ，",-1)),i(e,{href:"https://opensource.com/downloads/parted-cheat-sheet"},{default:t(()=>[...s[5]||(s[5]=[a("下載我們的 GNU Parted 速查表",-1)])]),_:1}),s[7]||(s[7]=a("，讓信息近在咫尺。",-1))]),s[29]||(s[29]=n("hr",null,null,-1)),n("p",null,[s[9]||(s[9]=a("via: ",-1)),i(e,{href:"https://opensource.com/article/21/4/linux-parted-cheat-sheet"},{default:t(()=>[...s[8]||(s[8]=[a("https://opensource.com/article/21/4/linux-parted-cheat-sheet",-1)])]),_:1})]),n("p",null,[s[14]||(s[14]=a("作者：",-1)),i(e,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[10]||(s[10]=[a("Seth Kenlon",-1)])]),_:1}),s[15]||(s[15]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[11]||(s[11]=[a("lujun9972",-1)])]),_:1}),s[16]||(s[16]=a(" 譯者：",-1)),i(e,{href:"https://github.com/hwlife"},{default:t(()=>[...s[12]||(s[12]=[a("hwlife",-1)])]),_:1}),s[17]||(s[17]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[13]||(s[13]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[20]||(s[20]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[18]||(s[18]=[a("LCTT",-1)])]),_:1}),s[21]||(s[21]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[19]||(s[19]=[a("Linux中國",-1)])]),_:1}),s[22]||(s[22]=a(" 榮譽推出",-1))])])}const v=l(h,[["render",u]]);export{x as __pageData,v as default};
